 async function saveWebsiteRelease(e:React.FormEvent){
  e.preventDefault();if(!supabase)return;
  const version=String(releaseSettings.version_name||"").trim(),tag=String(releaseSettings.release_tag||"").trim(),code=Number(releaseSettings.version_code);
  if(!/^\d+\.\d+\.\d+(?:[-+][a-zA-Z0-9.-]+)?$/.test(version)){setError("Enter a version such as 3.5.2.");return;}
  if(!/^v\d+\.\d+\.\d+(?:-[a-zA-Z0-9.-]+)?$/.test(tag)){setError("Release tag must look like v3.5.2.");return;}
  if(!Number.isInteger(code)||code<1){setError("Version code must be a positive whole number.");return;}
  setBusy(true);setError("");
  const {error}=await supabase.from("app_release_settings").update({version_name:version,version_code:code,release_tag:tag,is_available:Boolean(releaseSettings.is_available),updated_at:new Date().toISOString()}).eq("id",1);
  if(error)setError(error.message);else{setReleaseSettings((v:Row)=>({...v,version_name:version,version_code:code,release_tag:tag}));setMessage("Website download version settings saved.");}
  setBusy(false);
 }
 async function uploadPyqPaper(e:React.FormEvent){
  e.preventDefault();if(!supabase||!pyqFile)return;
  const year=Number(pyqYear),title=pyqTitle.trim(),exam=pyqExam.trim();
  if(!title||!exam||!Number.isInteger(year)||year<2000||year>2100){setError("Enter a paper title, exam name and valid year.");return;}
  if(pyqFile.type!=="application/pdf"&&!pyqFile.name.toLowerCase().endsWith(".pdf")){setError("Only PDF files are supported.");return;}
  if(pyqFile.size>50*1024*1024){setError("PDF must be 50 MB or smaller.");return;}
  setBusy(true);setError("");setMessage("");
  const safeName=pyqFile.name.replace(/[^a-zA-Z0-9._-]/g,"-");
  const path=year+"/"+Date.now()+"-"+safeName;
  try{
   const {error:uploadError}=await supabase.storage.from("pyq-papers").upload(path,pyqFile,{contentType:"application/pdf",upsert:false});
   if(uploadError)throw uploadError;
   const {data,error}=await supabase.from("pyq_papers").insert({title,exam_name:exam,exam_year:year,description:pyqDescription.trim()||null,paper_file_path:path,access_tier:"free",status:"published",published_at:new Date().toISOString(),created_by:session?.user?.id||null}).select().single();
   if(error){await supabase.storage.from("pyq-papers").remove([path]);throw error;}
   setPyqPapers(v=>[data,...v].sort((a,b)=>b.exam_year-a.exam_year));setPyqTitle("");setPyqDescription("");setPyqFile(null);setMessage("PDF uploaded and published. It will appear in the app without adding individual MCQs.");
  }catch(err){setError(err instanceof Error?err.message:"Could not upload the PDF paper.");}
  finally{setBusy(false);}
 }
