 async function saveQuestion(e:React.FormEvent){
  e.preventDefault();
  if(!supabase||!editing)return;
  setError("");setMessage("");
  const options=Array.isArray(editing.options)?editing.options.map((value:any)=>String(value??"").trim()):[];
  if(!editing.chapter_id){setError("Choose a chapter before saving the question.");return;}
  if(!String(editing.prompt||"").trim()){setError("Enter the question prompt.");return;}
  if(options.length!==4||options.some((value:string)=>!value)){setError("Enter all four answer options.");return;}
  if(!["A","B","C","D"].includes(String(editing.answer_key||"").toUpperCase())){setError("Choose the correct answer option.");return;}
  setBusy(true);
  try{
   const payload={...editing,chapter_id:String(editing.chapter_id),prompt:String(editing.prompt).trim(),options,answer_key:String(editing.answer_key).toUpperCase(),source_type:editing.source_type||"practice",topic_id:editing.topic_id||null,source_year:editing.source_year===""?null:editing.source_year,source_question_number:editing.source_question_number===""?null:editing.source_question_number,tags:Array.isArray(editing.tags)?editing.tags:[]};
   const {data,error}=await supabase.rpc("admin_upsert_question",{p_question:payload});
   if(error)throw error;
   if(!data)throw new Error("The database did not confirm that the question was saved. Please retry.");
   setMessage(editing.id?"Question updated successfully.":"Question submitted successfully.");
   setEditing(null);
   await reloadQuestions();
   await loadStatsOnly();
  }catch(err){
   setError(err instanceof Error?err.message:"Could not submit the question. Check your connection and try again.");
  }finally{setBusy(false)}
 }

